def compute(vars):
    tax_benefit = vars["v1"]
    compensation_cost = vars["v2"]
    if compensation_cost == 0:
        return None
    percent = abs(tax_benefit) / compensation_cost * 100
    return {
        "value": percent,
        "trace": {
            "income_tax_benefit": tax_benefit,
            "share_based_compensation_cost": compensation_cost,
            "benefit_percent_of_cost": percent,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
